export async function handlePaymentCaptured(msg: QueueMessage, db: Pool): Promise<void> {
  const evt = JSON.parse(msg.body) as PaymentCaptured; // { paymentId, userId, amountCents }
  const client = await db.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      "UPDATE wallets SET balance_cents = balance_cents + $1 WHERE user_id = $2", //!issue:1
      [evt.amountCents, evt.userId],
    );
    await client.query(
      "INSERT INTO wallet_ledger (user_id, amount_cents, reason) VALUES ($1, $2, 'payment_captured')",
      [evt.userId, evt.amountCents],
    );
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
  await msg.ack();
}

