func (h *Handler) HandlePaymentCaptured(ctx context.Context, msg *queue.Message) error {
	var evt PaymentCaptured // PaymentID, UserID, AmountCents
	if err := json.Unmarshal(msg.Body, &evt); err != nil {
		return err
	}
	tx, err := h.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx,
		"UPDATE wallets SET balance_cents = balance_cents + $1 WHERE user_id = $2", //!issue:1
		evt.AmountCents, evt.UserID); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx,
		"INSERT INTO wallet_ledger (user_id, amount_cents, reason) VALUES ($1, $2, 'payment_captured')",
		evt.UserID, evt.AmountCents); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	return msg.Ack(ctx)
}

