public void handlePaymentCaptured(QueueMessage msg) throws Exception {
    // record PaymentCaptured(UUID paymentId, UUID userId, long amountCents)
    PaymentCaptured evt = mapper.readValue(msg.body(), PaymentCaptured.class);
    try (Connection conn = dataSource.getConnection()) {
        conn.setAutoCommit(false);
        try {
            try (PreparedStatement credit = conn.prepareStatement(
                    "UPDATE wallets SET balance_cents = balance_cents + ? WHERE user_id = ?")) { //!issue:1
                credit.setLong(1, evt.amountCents());
                credit.setObject(2, evt.userId());
                credit.executeUpdate();
            }
            try (PreparedStatement ledger = conn.prepareStatement(
                    "INSERT INTO wallet_ledger (user_id, amount_cents, reason) VALUES (?, ?, 'payment_captured')")) {
                ledger.setObject(1, evt.userId());
                ledger.setLong(2, evt.amountCents());
                ledger.executeUpdate();
            }
            conn.commit();
        } catch (SQLException e) {
            conn.rollback();
            throw e;
        }
    }
    msg.ack();
}

