export async function placeOrder(db: Pool, producer: Producer, req: PlaceOrderRequest): Promise<Order> {
  const order = newOrder(req);
  const client = await db.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      "INSERT INTO orders (id, customer_id, total_cents, status) VALUES ($1, $2, $3, 'PLACED')",
      [order.id, order.customerId, order.totalCents],
    );
    await insertLineItems(client, order);
    await client.query("COMMIT"); //!issue:1
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
  try {
    await producer.send({ //!issue:1
      topic: "orders.placed",
      messages: [{ key: order.id, value: JSON.stringify(toEvent(order)) }],
    });
  } catch (err) {
    logger.error({ err, orderId: order.id }, "failed to publish order placed");
  }
  return order;
}

