export async function compactPartition(locks: LockClient, store: ObjectStore, partition: string): Promise<void> {
  const lease = await locks.acquire(`compact/${partition}`, { ttlMs: 30_000 });
  if (!lease) return; // another worker owns it
  try {
    const segments = await store.listSegments(partition);
    const merged = await mergeSegments(segments); // 20-60 s on large partitions
    if (!(await lease.isValid())) { //!issue:1
      throw new Error(`lease lost for ${partition}`);
    }
    await store.putManifest(partition, merged.manifest); //!issue:1
    await store.deleteSegments(partition, segments);
  } finally {
    await lease.release();
  }
}

