func CompactPartition(ctx context.Context, locks LockClient, store ObjectStore, partition string) error {
	lease, err := locks.Acquire(ctx, "compact/"+partition, 30*time.Second)
	if errors.Is(err, ErrLockHeld) {
		return nil // another worker owns it
	}
	if err != nil {
		return err
	}
	defer lease.Release(context.Background())

	segments, err := store.ListSegments(ctx, partition)
	if err != nil {
		return err
	}
	merged, err := MergeSegments(ctx, segments) // 20-60 s on large partitions
	if err != nil {
		return err
	}
	if !lease.Valid() { //!issue:1
		return fmt.Errorf("lease lost for %s", partition)
	}
	if err := store.PutManifest(ctx, partition, merged.Manifest); err != nil { //!issue:1
		return err
	}
	return store.DeleteSegments(ctx, partition, segments)
}

