pub async fn compact_partition(locks: &LockClient, store: &ObjectStore, partition: &str) -> anyhow::Result<()> {
    let Some(lease) = locks.acquire(&format!("compact/{partition}"), Duration::from_secs(30)).await? else {
        return Ok(()); // another worker owns it
    };
    let result: anyhow::Result<()> = async {
        let segments = store.list_segments(partition).await?;
        let merged = merge_segments(&segments).await?; // 20-60 s on large partitions
        if !lease.is_valid().await { //!issue:1
            anyhow::bail!("lease lost for {partition}");
        }
        store.put_manifest(partition, &merged.manifest).await?; //!issue:1
        store.delete_segments(partition, &segments).await?;
        Ok(())
    }
    .await;
    lease.release().await?;
    result
}

