public void compactPartition(String partition) throws Exception {
    Optional<Lease> maybeLease = locks.tryAcquire("compact/" + partition, Duration.ofSeconds(30));
    if (maybeLease.isEmpty()) {
        return; // another worker owns it
    }
    try (Lease lease = maybeLease.get()) {
        List<Segment> segments = store.listSegments(partition);
        MergeResult merged = mergeSegments(segments); // 20-60 s on large partitions
        if (!lease.isValid()) { //!issue:1
            throw new LeaseLostException("lease lost for " + partition);
        }
        store.putManifest(partition, merged.manifest()); //!issue:1
        store.deleteSegments(partition, segments);
    }
}
